def build(data=None,out=OUT):
    from experience_pages import daylight, three
    data=load_data() if data is None else data
    validate_data(data);out=Path(out);out.mkdir(parents=True,exist_ok=True)
    pages=[('11_城市运行大屏.html',daylight(data)),('12_城市设施夜景大屏.html',night_observatory(data)),('13_三维城市探索.html',three(data))]
    for name,text in pages:
        (out/name).write_text(text,encoding='utf-8');print('HTML',name)

if __name__=='__main__':build()
